module.exports = async function (url, gRazerEndpoint, timeout) {
  const options = {};
  if (gRazerEndpoint) {
    options.headers = {
      'x-rzr-endpoint': gRazerEndpoint,
    };
  }
  if (typeof timeout === 'number') {
    // node-fetch v3 dropped options.timeout; use AbortSignal (Node 17.3+).
    options.signal = AbortSignal.timeout(timeout);
  }
  options.agent = createAgent(url);
  console.log(...LOG_MSG, 'Making request to:', url, options.headers, options.agent?.proxy);
  const response = await fetch(url, options);

  if (response.ok) {
    const text = await response.text();
    console.log(...LOG_MSG, `Request ${url} succeeded with status`, response.status, 'and text', text);
    return text;
  } else {
    console.warn(...LOG_MSG, `Request ${url} failed with status ${response.status}`);
    return;
  }
}

